'use strict';
const wreckCurrentPosition=[-27.16304,153.36826];
function currentHazardContent(){return `<div class="current-state"><strong>Current strength now: unknown</strong><span>Documented hazard · no live current measurement</span></div><h4>Where the risk is</h4><p>Tangalooma Resort warns of strong tidal flow between the wrecks and the beach when the tide is running. The marker identifies the wrecks reference location; it does not outline the full hazard area or mark an entry point.</p><h4>What determines the current?</h4><dl class="current-factors"><dt>Tidal flow</dt><dd>Water moving into and out of Moreton Bay produces tidal currents. A rising or falling water level alone does not tell us the speed at the wrecks.</dd><dt>Spring–neap cycle</dt><dd>Tidal currents generally strengthen around new and full moons and weaken around quarter moons. This is a general tendency, not a local safety forecast.</dd><dt>Seabed and channel shape</dt><dd>Depth and coastal geometry influence flow over short distances. Conditions in the shore-to-wreck gap can differ from a regional model or nearby tide gauge.</dd><dt>Wind and waves</dt><dd>Wind adds surface drift and waves can make the crossing harder. Calm-looking water is not evidence of weak current.</dd></dl><h4>High tide is not a slack-water guarantee</h4><p>Slack water means a minimum in tidal-current speed. Its timing relative to high or low water depends on the location. No verified local slack-water offset is available in this guide, so it does not calculate a safe snorkelling window.</p><h4>Before entering</h4><p>Check current local operator advice and conditions on arrival. If the flow is strong, conditions are uncertain or the crossing exceeds your ability, do not enter. Do not attempt to swim against a strong running current. Go with a buddy and avoid climbing on or swimming through the wrecks.</p><div class="attribute"><b>Wrecks reference · UTM 56S</b>${formatUTM(...wreckCurrentPosition)}</div><p>Source-backed point, not a measured current boundary. No speed, direction or observation time is available.</p><h4>Evidence & conditions</h4><ul><li><a href="https://www.tangalooma.com/resort-info/general-resort-information/swim-safety" target="_blank" rel="noopener">Tangalooma Resort: local current warning</a></li><li><a href="https://www.qld.gov.au/environment/coasts-waterways/beach/tide-sites/tangalooma" target="_blank" rel="noopener">Tangalooma water-level observations and tide predictions</a> — height, not current velocity</li><li><a href="https://www.bom.gov.au/qld/forecasts/moreton-bay.shtml" target="_blank" rel="noopener">Moreton Bay wind and marine forecast</a></li><li><a href="https://www.cmar.csiro.au/remotesensing/oceancurrent/tides/" target="_blank" rel="noopener">CSIRO: tidal-current models and limitations</a> — regional depth-average predictions do not establish conditions in this narrow gap</li><li><a href="https://oceanservice.noaa.gov/education/tutorial_currents/02tidal1.html" target="_blank" rel="noopener">NOAA: spring and neap tidal currents</a></li><li><a href="https://oceanservice.noaa.gov/facts/current.html" target="_blank" rel="noopener">NOAA: wind and currents</a></li><li><a href="https://parks.qld.gov.au/parks/gheebulum-kunungai-moreton-island/things-to-do" target="_blank" rel="noopener">QPWS: snorkelling safety</a></li><li><a href="https://mapcarta.com/N4406047102" target="_blank" rel="noopener">Reference position: OpenStreetMap via Mapcarta</a></li></ul><p>Guidance reviewed 24 October 2026. This is not a live conditions report.</p>`;}
function showCurrentHazard(){
 $('#featurePanel').hidden=false;$('#featureTitle').textContent='Tangalooma Wrecks · currents';$('#featureAttributes').innerHTML=currentHazardContent();
}
function setupCurrents(){
 const group=document.createElement('details');group.className='layergroup';group.open=true;
 group.innerHTML='<summary>Water currents & snorkelling</summary><label><input type="checkbox" id="currentHazards" checked><span class="legend-icon warning" style="--layer-color:#ac4a20" aria-hidden="true">!</span><span>Wrecks current hazard</span></label><p>Documented hazard point. Current speed and direction are not measured.</p><button id="inspectCurrents" class="current-open">Inspect wrecks currents</button>';
 $('#layerOptions').prepend(group);
 const marker=L.marker(wreckCurrentPosition,{icon:L.divIcon({className:'current-hazard-pin',html:'<span aria-hidden="true">!</span>',iconSize:[30,30],iconAnchor:[15,15]}),title:'Tangalooma Wrecks: current hazard — live strength unknown',alt:'Current hazard at Tangalooma Wrecks'}).on('click',()=>{if(!measuring)showCurrentHazard()});
 marker.addTo(map);
 $('#currentHazards').onchange=e=>{if(e.target.checked)marker.addTo(map);else map.removeLayer(marker)};
 const focus=()=>{tab('explore');$('#currentHazards').checked=true;marker.addTo(map);map.setView(wreckCurrentPosition,16);showCurrentHazard()};
 $('#inspectCurrents').onclick=focus;
 const card=document.createElement('article');card.className='card';card.innerHTML='<h2>Wrecks current hazard</h2><p>Tidal flow between the beach and the wrecks can be strong. High or low tide does not establish slack current. Live current strength is unknown in this guide.</p><button id="conditionsCurrents" class="current-open">Inspect on map</button>';$('#conditionsCards').prepend(card);$('#conditionsCurrents').onclick=focus;
}
